import React from 'react';
import { Card, CardContent, CardHeader, CardTitle } from './card';
import { cn } from '../../lib/utils';

const StatsCard = ({ title, count, description, icon: Icon, iconColorClass, className }) => {
    return (
        <Card className={cn("hover:shadow-lg transition-all duration-300 border-l-4", className)}>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium text-muted-foreground">
                    {title}
                </CardTitle>
                {Icon && <Icon className={cn("h-4 w-4 text-muted-foreground", iconColorClass)} />}
            </CardHeader>
            <CardContent>
                <div className="text-2xl font-bold">{count}</div>
                {description && (
                    <p className="text-xs text-muted-foreground mt-1">
                        {description}
                    </p>
                )}
            </CardContent>
        </Card>
    );
};

export default StatsCard;
